(async () => {
  const f = document.querySelector('#quote-form');
  if (!f) return {error: 'no form'};
  f.querySelector('[name=name]').value = 'Browser Test';
  f.querySelector('[name=email]').value = 'browser@example.com';
  const phone = f.querySelector('[name=whatsapp]'); if (phone) phone.value = '+86 10000';
  const company = f.querySelector('[name=company]'); if (company) company.value = 'Browser Co';
  const msg = f.querySelector('[name=message]'); if (msg) msg.value = 'Testing the form end to end.';
  const sel = f.querySelector('[name=project_type]'); if (sel) sel.value = sel.options[1] ? sel.options[1].value : '';
  f.querySelector('[type=submit]').click();
  await new Promise(r => setTimeout(r, 2500));
  const s = document.querySelector('#quote-status');
  return { status: s ? s.textContent : 'no status', hidden: s ? s.hidden : null };
})()
